package steps;

import context.ScenarioContext;
import io.cucumber.datatable.DataTable;
import io.cucumber.java.en.Given;
import io.cucumber.java.en.Then;
import org.apache.pdfbox.pdmodel.PDDocumentInformation;
import org.testng.Assert;
import utils.PdfUtil;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Generic steps for validating generated PDFs (invoices, statements, reports) — text content,
 * page count, and metadata — via {@code utils.PdfUtil} (Apache PDFBox). The PDF is generated by
 * the {@code Given} step itself rather than produced by any real invoicing feature, since none
 * exists in this framework yet; point these same {@code Then} steps at a real generated PDF's
 * path once one does.
 */
public class PdfSteps {

    private static final String PDF_PATH_KEY = "currentPdfPath";
    private static final String PDF_FIXTURES_DIR = "target/pdf-fixtures/";

    private final ScenarioContext scenarioContext;

    public PdfSteps(ScenarioContext scenarioContext) {
        this.scenarioContext = scenarioContext;
    }

    @Given("a sample PDF {string} is generated with title {string} and author {string} containing:")
    public void aSamplePdfIsGeneratedWithTitleAndAuthorContaining(String fileName, String title, String author, DataTable dataTable) {
        List<String> lines = dataTable.asList(String.class);
        String path = PDF_FIXTURES_DIR + fileName;
        PdfUtil.createPdf(path, title, author, Collections.singletonList(lines));
        scenarioContext.set(PDF_PATH_KEY, path);
    }

    @Given("a sample PDF {string} is generated with {int} pages each containing the text {string}")
    public void aSamplePdfIsGeneratedWithPagesEachContainingText(String fileName, int pageCount, String text) {
        String path = PDF_FIXTURES_DIR + fileName;
        List<List<String>> pages = new ArrayList<>();
        for (int pageNumber = 1; pageNumber <= pageCount; pageNumber++) {
            pages.add(Collections.singletonList(text + " (page " + pageNumber + ")"));
        }
        PdfUtil.createPdf(path, null, null, pages);
        scenarioContext.set(PDF_PATH_KEY, path);
    }

    @Then("the PDF should have {int} page(s)")
    public void thePdfShouldHavePages(int expectedPageCount) {
        Assert.assertEquals(PdfUtil.pageCount(currentPdfPath()), expectedPageCount);
    }

    @Then("the PDF text should contain {string}")
    public void thePdfTextShouldContain(String expectedText) {
        String text = PdfUtil.extractText(currentPdfPath());
        Assert.assertTrue(text.contains(expectedText),
                "Expected PDF text to contain \"" + expectedText + "\" — actual text:\n" + text);
    }

    @Then("the PDF metadata title should be {string}")
    public void thePdfMetadataTitleShouldBe(String expectedTitle) {
        PDDocumentInformation info = PdfUtil.metadata(currentPdfPath());
        Assert.assertEquals(info.getTitle(), expectedTitle);
    }

    @Then("the PDF metadata author should be {string}")
    public void thePdfMetadataAuthorShouldBe(String expectedAuthor) {
        PDDocumentInformation info = PdfUtil.metadata(currentPdfPath());
        Assert.assertEquals(info.getAuthor(), expectedAuthor);
    }

    @Then("the PDF is attached to the Allure report")
    public void thePdfIsAttachedToTheAllureReport() {
        PdfUtil.attachToAllure("Generated PDF", currentPdfPath());
    }

    private String currentPdfPath() {
        return scenarioContext.get(PDF_PATH_KEY, String.class);
    }
}
